            graph[b].append(a)
        state = [0] * numCourses  # 0=未访问 1=访问中 2=已完成

        def dfs(course):
            if state[course] == 1:
                return False
            if state[course] == 2:
                return True
            state[course] = 1
            for nxt in graph[course]:
                if not dfs(nxt):
                    return False
            state[course] = 2
            return True

        for i in range(numCourses):
            if not dfs(i):
                return False
        return True

