from typing import List


class Solution:
    def coinChange(self, coins: List[int], amount: int) -> int:
        dp = [0] + [float("inf")] * amount
        for i in range(1, amount + 1):
            for c in coins:
                if c <= i:
                    dp[i] = min(dp[i], dp[i - c] + 1)
        return dp[amount] if dp[amount] != float("inf") else -1

from typing import List


class Solution:
    def coinChange(self, coins: List[int], amount: int) -> int:
        memo = {}

        def dfs(remain):
            if remain == 0:
                return 0
            if remain < 0:
                return -1
            if remain in memo:
                return memo[remain]
            best = float("inf")
            for c in coins:
                r = dfs(remain - c)
                if r >= 0:
                    best = min(best, r + 1)
            memo[remain] = best if best != float("inf") else -1
            return memo[remain]

        return dfs(amount)

import sys


def solve():
    lines = sys.stdin.read().splitlines()
    coins = list(map(int, lines[0].split()))
    amount = int(lines[1])
    dp = [0] + [float("inf")] * amount
    for i in range(1, amount + 1):
        for c in coins:
            if c <= i:
                dp[i] = min(dp[i], dp[i - c] + 1)
    print(dp[amount] if dp[amount] != float("inf") else -1)


if __name__ == "__main__":
    solve()

