class Solution:
    def decodeString(self, s: str) -> str:
        stack = []
        cur_num = 0
        cur_str = ""
        for ch in s:
            if ch.isdigit():
                cur_num = cur_num * 10 + int(ch)
            elif ch == "[":
                stack.append((cur_str, cur_num))
                cur_str = ""
                cur_num = 0
            elif ch == "]":
                prev_str, num = stack.pop()
                cur_str = prev_str + num * cur_str
            else:
                cur_str += ch
        return cur_str

class Solution:
    def decodeString(self, s: str) -> str:
        def helper(i):
            res = ""
            num = 0
            while i < len(s):
                ch = s[i]
                if ch.isdigit():
                    num = num * 10 + int(ch)
                elif ch == "[":
                    sub, i = helper(i + 1)
                    res += num * sub
                    num = 0
                elif ch == "]":
                    return res, i
                else:
                    res += ch
                i += 1
            return res, i

        return helper(0)[0]

